/**
 * Identifiers the Serial Send Box shares with package.json's macro keybinding
 * twins (generated by scripts/generateKeybindings.mjs). Kept free of `vscode`
 * so the manifest test can import them and pin the two together.
 */

/** The webview viewType; the twins match it through `activeWebviewPanelId`. */
export const SERIAL_SEND_VIEW_TYPE = "nexus.serialSend";

/**
 * True while keyboard focus is inside a Serial Send Box. The send-box twins of
 * the macro keybindings use it, together with `!terminalFocus && !sideBarFocus
 * && !panelFocus && !auxiliaryBarFocus && !inQuickOpen` (this key is cleared
 * only after the page's blur report arrives; those are set synchronously when
 * focus moves) and `activeWebviewPanelId == 'nexus.serialSend'`. That built-in
 * key alone is not enough: VS Code derives it from the active editor of the
 * active editor group (webviewWorkbenchService.ts registers it as an
 * editor-group context-key provider), so it stays set while focus is in the
 * sidebar, a panel or quick input. VS Code exposes no webview-focus key to
 * extensions, so the page reports its own window focus/blur and SerialSendPanel
 * keeps the key in step.
 */
export const SERIAL_SEND_FOCUS_CONTEXT = "nexus.serialSendBoxFocused";
